from collections import deque

def get_components(grid):
    """Find all connected components (4-directional)."""
    H, W = len(grid), len(grid[0])
    components = []
    visited = [[False]*W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = []
                queue = deque([(r, c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    comp.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != 0 and not visited[nr][nc]:
                            visited[nr][nc] = True
                            queue.append((nr, nc))
                components.append(comp)
    return components

def center_of(cells):
    """Compute center of a set of cells."""
    if not cells:
        return (0, 0)
    coords = [(r,c) for r,c in cells]
    r_mean = sum(r for r,c in coords) / len(coords)
    c_mean = sum(c for r,c in coords) / len(coords)
    return (round(r_mean), round(c_mean))

def get_bbox(cells):
    if not cells:
        return (0,0,0,0)
    coords = [(r,c) for r,c in cells]
    rmin, rmax = min(r for r,c in coords), max(r for r,c in coords)
    cmin, cmax = min(c for r,c in coords), max(c for r,c in coords)
    return (rmin, cmin, rmax-rmin+1, cmax-cmin+1)

