def count_mod_pattern(grid, h_out, w_out):
    """Count dots at each mod position."""
    counts = [[0 for _ in range(w_out)] for _ in range(h_out)]
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                counts[r % h_out][c % w_out] += 1
    return counts

