def region_density(grid, h_out, w_out):
    """Compute density (count of foreground cells) in each region."""
    H, W = len(grid), len(grid[0])
    result = [[0 for _ in range(w_out)] for _ in range(h_out)]

    for r in range(h_out):
        for c in range(w_out):
            rmin, rmax = r * H // h_out, (r + 1) * H // h_out
            cmin, cmax = c * W // w_out, (c + 1) * W // w_out

            # Count non-zero cells, or sum their values
            density = sum(grid[rr][cc] if grid[rr][cc] != 0 else 0 
                         for rr in range(rmin, rmax)
                         for cc in range(cmin, cmax))
            result[r][c] = density

    return result

